<?php
class SafeFormula
{
    public static function evaluate(?string $formula,array $values): float{$formula=trim((string)$formula);if($formula==='')return 0.0;if(strlen($formula)>1000||preg_match('/[^a-zA-Z0-9_+\-*\/().\s]/',$formula))throw new InvalidArgumentException('فرمول شامل نویسه غیرمجاز است.');$tokens=[];preg_match_all('/[a-zA-Z_][a-zA-Z0-9_]*|\d+(?:\.\d+)?|[()+\-*\/]/',$formula,$m);$tokens=$m[0];if(implode('',array_map(static fn($t)=>preg_replace('/\s/','',$t),$tokens))!==preg_replace('/\s/','',$formula))throw new InvalidArgumentException('ساختار فرمول معتبر نیست.');$out=[];$ops=[];$prec=['+'=>1,'-'=>1,'*'=>2,'/'=>2];foreach($tokens as $token){if(is_numeric($token))$out[]=(float)$token;elseif(preg_match('/^[a-zA-Z_]/',$token)){$out[]=(float)($values[$token]??0);}elseif(isset($prec[$token])){while($ops&&end($ops)!=='('&&$prec[end($ops)]>=$prec[$token])$out[]=array_pop($ops);$ops[]=$token;}elseif($token==='(')$ops[]=$token;elseif($token===')'){while($ops&&end($ops)!=='(')$out[]=array_pop($ops);if(!$ops)throw new InvalidArgumentException('پرانتز فرمول معتبر نیست.');array_pop($ops);}}while($ops){$op=array_pop($ops);if($op==='(')throw new InvalidArgumentException('پرانتز فرمول معتبر نیست.');$out[]=$op;}$stack=[];foreach($out as $token){if(is_float($token)||is_int($token)){$stack[]=(float)$token;continue;}if(count($stack)<2)throw new InvalidArgumentException('فرمول ناقص است.');$b=array_pop($stack);$a=array_pop($stack);$stack[]=match($token){'+'=>$a+$b,'-'=>$a-$b,'*'=>$a*$b,'/'=>abs($b)<0.0000001?0:$a/$b};}if(count($stack)!==1)throw new InvalidArgumentException('فرمول معتبر نیست.');return round((float)$stack[0],4);}
}
